/* Register gcregWindowControl **
** ~~~~~~~~~~~~~~~~~~~~~~~~~~~ */

/* L2 window control. */

#define gcregWindowControlRegAddrs                                        0x0E0F
#define GCREG_WINDOW_CONTROL_Address                                     0x0383C
#define GCREG_WINDOW_CONTROL_MSB                                              15
#define GCREG_WINDOW_CONTROL_LSB                                               0
#define GCREG_WINDOW_CONTROL_BLK                                               0
#define GCREG_WINDOW_CONTROL_Count                                             1
#define GCREG_WINDOW_CONTROL_FieldMask                                0x00000333
#define GCREG_WINDOW_CONTROL_ReadMask                                 0x00000333
#define GCREG_WINDOW_CONTROL_WriteMask                                0x00000333
#define GCREG_WINDOW_CONTROL_ResetValue                               0x00000000

/* Enable L2 windowing for color.  All addresses will be offsets into the L2  **
** cache for reading/writing.  Only the resolve will actually write to DDR    **
** memory.                                                                    */
#define GCREG_WINDOW_CONTROL_COLOR                                           1:0
#define GCREG_WINDOW_CONTROL_COLOR_End                                         1
#define GCREG_WINDOW_CONTROL_COLOR_Start                                       0
#define GCREG_WINDOW_CONTROL_COLOR_Type                                      U02
#define   GCREG_WINDOW_CONTROL_COLOR_DISABLE                                 0x0
#define   GCREG_WINDOW_CONTROL_COLOR_INTERNAL                                0x1
#define   GCREG_WINDOW_CONTROL_COLOR_EXTERNAL                                0x2

/* Enable L2 windowing for depth.  All addresses will be offsets into the L2  **
** cache for reading/writing.                                                 */
#define GCREG_WINDOW_CONTROL_DEPTH                                           5:4
#define GCREG_WINDOW_CONTROL_DEPTH_End                                         5
#define GCREG_WINDOW_CONTROL_DEPTH_Start                                       4
#define GCREG_WINDOW_CONTROL_DEPTH_Type                                      U02
#define   GCREG_WINDOW_CONTROL_DEPTH_DISABLE                                 0x0
#define   GCREG_WINDOW_CONTROL_DEPTH_INTERNAL                                0x1
#define   GCREG_WINDOW_CONTROL_DEPTH_EXTERNAL                                0x2

/* Enable L2 windowing for vertex and index streams.  The L2 cache will read  **
** data until the cache is full, after which it will just fetch the data from **
** DDR.  The cashe needs to be invalidated when a new frame starts (after all **
** windows have been processed for the current render buffer).                */
#define GCREG_WINDOW_CONTROL_STREAMS                                         9:8
#define GCREG_WINDOW_CONTROL_STREAMS_End                                       9
#define GCREG_WINDOW_CONTROL_STREAMS_Start                                     8
#define GCREG_WINDOW_CONTROL_STREAMS_Type                                    U02
#define   GCREG_WINDOW_CONTROL_STREAMS_DISABLE                               0x0
#define   GCREG_WINDOW_CONTROL_STREAMS_ENABLE                                0x1
#define   GCREG_WINDOW_CONTROL_STREAMS_INVALIDATE                            0x2

