/*******************************************************************************
**                                ~~~~~~~~~~~~~                               **
**                                Command Token                               **
**                                ~~~~~~~~~~~~~                               **
*******************************************************************************/

/* Offset gcdefToken
** ~~~~~~~~~~~~~~~~~ */

#define GCDEF_TOKEN_OPCODE                                                   3:0
#define GCDEF_TOKEN_OPCODE_End                                                 3
#define GCDEF_TOKEN_OPCODE_Start                                               0
#define GCDEF_TOKEN_OPCODE_Type                                              U04
/* Sent by FE to inform a reset of the primitive ID. */
#define   GCDEF_TOKEN_OPCODE_RESET_PRIMITIVE_ID                              0x0
/* Sent by TPG to inform end of patch. */
#define   GCDEF_TOKEN_OPCODE_END_OF_PATCH                                    0x1
/* Sent by FE to inform end of draw. */
#define   GCDEF_TOKEN_OPCODE_END_OF_DRAW                                     0x2
/* Close a shader group. Same as EndOfDraw except that the result cache is    **
** not flushed.                                                               */
#define   GCDEF_TOKEN_OPCODE_CLOSE_GROUP                                     0x3
/* Change the state set for RTL. */
#define   GCDEF_TOKEN_OPCODE_CHANGE_STATE_SET                                0x4
/* Mark the beginning of a state load out of the bottom of the g-pipe shader. */
#define   GCDEF_TOKEN_OPCODE_STATE_OUT_BOTTOM                                0x5
/* Release the partial page and snap to the next page boundary. */
#define   GCDEF_TOKEN_OPCODE_SNAP_TO_PAGE                                    0x6
/* Increase Primitive ID, sent by WD. */
#define   GCDEF_TOKEN_OPCODE_INCREASE_PRIMITIVE_ID                           0x7
/* switch from stateLoad, sent by WD to PPA. */
#define   GCDEF_TOKEN_OPCODE_START_DATA                                      0x8
/* Reset InstanceID, sent by FE. */
#define   GCDEF_TOKEN_OPCODE_RESET_INSTANCE_ID                               0x9
/* Reset states. */
#define   GCDEF_TOKEN_OPCODE_RESET_STATE_SET                                 0xA
/* Set the Primitive ID, send by WD to GPIPE.  */
#define   GCDEF_TOKEN_OPCODE_SET_PRIMITIVE_ID                                0xB
/* flush WD deferred vertices. */
#define   GCDEF_TOKEN_OPCODE_FLUSH_WD_VTX_COMPLETIONS                        0xC
/* PPA Invaild 2 line cache.  */
#define   GCDEF_TOKEN_OPCODE_INVALIDATE_PPA2_LINE_CACHE                      0xD
/* Increment the binner data structure index by provided 20-bit payload. */
#define   GCDEF_TOKEN_OPCODE_BINPTR_INC                                      0xE
/* Sent by TPG to inform end of TPG Batch. */
#define   GCDEF_TOKEN_OPCODE_END_OF_TPG_BATCH                                0xF

/* Client selection bit. */
#define GCDEF_TOKEN_CLIENT                                                   8:4
#define GCDEF_TOKEN_CLIENT_End                                                 8
#define GCDEF_TOKEN_CLIENT_Start                                               4
#define GCDEF_TOKEN_CLIENT_Type                                              U05
/* No client selected. */
#define   GCDEF_TOKEN_CLIENT_NONE                                           0x00
/* Release VS partial page. */
#define   GCDEF_TOKEN_CLIENT_VS                                             0x01
/* Release TCS partial page. */
#define   GCDEF_TOKEN_CLIENT_TCS                                            0x02
/* Release TES partial page. */
#define   GCDEF_TOKEN_CLIENT_TES                                            0x04
/* Release GS partial page. */
#define   GCDEF_TOKEN_CLIENT_GS                                             0x08
/* Release PS/CS partial page. */
#define   GCDEF_TOKEN_CLIENT_PS                                             0x10


#endif /* __AQCommon_h__ */
